function buildOpenLearnCourses(L){const base='https://www.open.edu/openlearn/',electronics=base+'science-maths-technology/an-introduction-electronics/content-section-0',projects=base+'money-business/leadership-management/project-management-the-start-the-project-journey/content-section-0';const C=(id,title,domain,glyph,url,original,rows)=>({id,title,en:title,domain,glyph,color:'#dce6eb',desc:'Sélection de notions adaptée en français à partir d’un cours gratuit OpenLearn. Explications, exemples et quiz dans Nunya ; adaptation partielle à relire.',enDesc:'Adaptation française partielle',category:'OPENLEARN · ADAPTATION FRANÇAISE',type:'subject',level:'Découverte',duration:rows.length*12,track:'future',provider:'The Open University / OpenLearn',author:'The Open University ; adaptation française et exercices par Nunya',source_url:url,original_title:original,license:'CC BY-NC — conditions de la source',license_url:'https://about.open.ac.uk/strategy-and-policies/policies-and-statements/copyright-openlearn',source_notes:'Sélection et reformulation française non officielle. Exemples et quiz Nunya. Aucun média tiers, badge, diplôme ou cours complet revendiqué.',status:'brouillon',reviewer:null,adaptation_coverage:'partial',lessons:rows.map(r=>L(...r))});return [
C('ou-electronique-fr','OpenLearn : découvrir l’électronique en français','physics','Ω',electronics,'An introduction to electronics',[
['Distinguer tension, courant et résistance','La tension représente une différence de potentiel électrique et s’exprime en volts (V). Le courant mesure un débit de charge et s’exprime en ampères (A). La résistance s’exprime en ohms (Ω). Ces grandeurs décrivent des aspects différents d’un circuit : on ne les additionne pas comme si elles avaient la même unité. Dans cette adaptation, on raisonne uniquement sur des schémas et des valeurs fictives, sans manipulation d’installation.','Tension U : volt (V)\nCourant I : ampère (A)\nRésistance R : ohm (Ω)','Trois grandeurs, trois unités.','L’unité du courant électrique est…',['le volt','l’ampère','l’ohm'],1,'L’ampère mesure le courant ; le volt mesure une tension et l’ohm une résistance.'],
['Utiliser la loi d’Ohm dans un modèle','Pour une résistance idéale dans les conditions du modèle, la relation est U = RI. On peut en déduire I = U/R lorsque R n’est pas nul. Convertis les milliampères en ampères et les kilo-ohms en ohms avant le calcul. La relation d’une résistance idéale n’est pas une description universelle de tous les composants électroniques.','Modèle : U = 6 V ; R = 300 Ω\nI = 6 / 300 = 0,020 A\n0,020 A = 20 mA','Le courant calculé est 20 mA.','Pour U = 9 V et R = 450 Ω, I vaut…',['20 mA','2 A','50 mA'],0,'9/450 = 0,020 A, soit 20 mA.'],
['Un diviseur de tension à vide','Deux résistances en série peuvent former un diviseur. Si la sortie aux bornes de R2 ne fournit pratiquement aucun courant à une autre charge, U_sortie = U_entrée × R2/(R1 + R2). L’hypothèse de sortie à vide compte : ajouter une charge peut modifier le résultat. Cet exercice est un calcul, pas une consigne de montage réel.','U_entrée = 10 V ; R1 = 1 000 Ω ; R2 = 1 000 Ω\nU_sortie = 10 × 1 000/(1 000 + 1 000)\nU_sortie = 5 V','La sortie à vide vaut 5 V dans ce modèle.','Avec deux résistances égales et une entrée de 8 V, la sortie à vide vaut…',['8 V','2 V','4 V'],2,'Le rapport R2/(R1 + R2) vaut 1/2. La tension de sortie vaut donc 8/2 = 4 V.'],
['Relier capteur, traitement et action','Un système électronique peut recueillir une information, appliquer une règle et commander une action. Un capteur produit un signal lié à une grandeur ; la logique traite ce signal ; un actionneur agit. Dans un exemple fictif d’éclairage automatique, on peut décrire cette chaîne sur papier et discuter de ses limites, comme une mesure bruitée ou une règle mal choisie.','Information : niveau de lumière fictif\nRègle : comparer à un seuil\nAction : commander un éclairage simulé\nRetour : vérifier si l’action correspond au besoin','Un système peut être décrit comme une chaîne de fonctions.','Quel élément transforme une commande en action ?',['L’actionneur','La date du document','Le titre du schéma'],0,'L’actionneur réalise l’action commandée. Un capteur recueille une information.']
]),
C('ou-projet-fr','OpenLearn : préparer un projet en français','business','◇',projects,'Project management: the start of the project journey',[
['Définir le projet et son résultat','Un projet vise un résultat particulier dans un cadre de temps et de ressources. Il se distingue d’une opération répétée en continu. Commence par exprimer le résultat attendu et un critère permettant de reconnaître qu’il est atteint. L’exemple Nunya est fictif : préparer une exposition scolaire avec trois panneaux avant une date convenue.','Résultat : trois panneaux lisibles\nÉchéance : date convenue avec le groupe\nCritère : chaque panneau présente une idée et sa source','Un résultat vérifiable plutôt qu’une intention vague.','Quelle formulation décrit un résultat vérifiable ?',['Faire quelque chose de bien','Produire trois panneaux relus','Travailler beaucoup'],1,'Trois panneaux relus constituent un livrable que l’on peut observer et vérifier.'],
['Repérer les acteurs et leurs attentes','Un projet concerne plusieurs personnes ou groupes : ceux qui réalisent le travail, ceux qui utilisent le résultat et ceux qui peuvent l’influencer. Il faut comprendre leurs attentes et les contraintes, plutôt que supposer un accord général. Dans ton exercice, note un rôle, une attente et une question à clarifier pour chaque acteur fictif.','Élèves : comprendre le message\nÉquipe : connaître les tâches\nEncadrant : vérifier les sources\nQuestion : qui valide la version finale ?','Une carte simple des rôles et attentes.','Faut-il seulement considérer les personnes qui réalisent les tâches ?',['Oui','Non','Seulement à la fin'],1,'Les utilisateurs et les personnes influençant le projet comptent aussi dans sa préparation.'],
['Vérifier la faisabilité et l’incertitude','Une idée peut être intéressante tout en demandant trop de temps ou de moyens. Une vérification de faisabilité examine ce qui est réalisable et ce qui reste incertain. Distingue une contrainte déjà connue d’un risque futur. Prévois une réponse proportionnée et un petit test quand une hypothèse importante peut être vérifiée avant de s’engager.','Contrainte : trois séances disponibles\nRisque : une impression tardive\nRéponse : préparer une version manuscrite de secours\nTest : faire relire le premier panneau tôt','Des contraintes et des risques rendus visibles.','Quel élément est un risque futur dans cet exemple ?',['Le retard d’impression possible','Le nombre de séances déjà fixé','Le titre du projet'],0,'Un retard possible est un événement incertain. Les trois séances constituent une contrainte connue.'],
['Avancer par étapes et apprendre du retour','Le cycle d’un projet relie préparation, réalisation et bilan. Selon le contexte, on peut planifier des étapes successives ou essayer rapidement un prototype, puis l’améliorer. Le suivi compare le résultat au besoin et aide à adapter le travail. Après ton projet fictif, garde une réussite, une difficulté et une amélioration pour la prochaine fois.','Préparer → essayer un premier panneau → recevoir un retour\nAméliorer → finaliser → faire le bilan','Une première version permet d’apprendre avant de tout produire.','Pourquoi montrer un prototype tôt ?',['Pour éviter toute vérification','Pour obtenir un retour avant de finaliser','Pour prouver que le projet est terminé'],1,'Un retour précoce aide à corriger le résultat pendant qu’il est encore facile à modifier.']
])];}
